3	eventReminder	\N	<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <title>Nhắc Nhở Sự Kiện - Alumniverse</title>\n    <style>\n        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f5f5f5; margin: 0; padding: 0; }\n        .container { background-color: white; max-width: 600px; margin: 20px auto; padding: 30px; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }\n        .header { text-align: center; margin-bottom: 30px; border-bottom: 2px solid #667eea; padding-bottom: 20px; }\n        .header h1 { color: #333; margin: 0; font-size: 24px; }\n        .header p { color: #666; font-size: 14px; margin: 5px 0 0 0; }\n        .reminder-banner { background-color: #fff3e0; border-left: 4px solid #ff9800; padding: 15px; margin: 20px 0; border-radius: 4px; font-size: 14px; color: #e65100; font-weight: bold; }\n        .event-box { background-color: #f0f7ff; border-left: 4px solid #667eea; padding: 20px; margin: 20px 0; border-radius: 4px; }\n        .event-title { font-size: 18px; font-weight: bold; color: #333; margin-bottom: 12px; }\n        .event-detail { display: flex; margin: 8px 0; font-size: 14px; color: #555; }\n        .event-detail .label { color: #888; min-width: 100px; }\n        .custom-body { background-color: #f9f9f9; border: 1px solid #eee; padding: 16px; border-radius: 4px; font-size: 14px; color: #333; line-height: 1.7; margin: 20px 0; }\n        .footer { text-align: center; margin-top: 30px; padding-top: 20px; border-top: 1px solid #eee; font-size: 12px; color: #999; }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="header">\n            <h1>Nhắc nhở tham gia sự kiện</h1>\n            <p>Hệ Thống Quản Lý Sinh Viên - Cựu Sinh Viên HCMUS</p>\n        </div>\n\n        <div class="reminder-banner">\n             Sự kiện sắp diễn ra! Đừng quên tham gia.\n        </div>\n\n        <div class="event-box">\n            <div class="event-title" th:text="${eventTitle}">Tên sự kiện</div>\n            <div class="event-detail">\n                <span class="label">📍 Địa điểm:</span>\n                <span th:text="${eventLocation}">Địa điểm</span>\n            </div>\n            <div class="event-detail">\n                <span class="label">🕐 Thời gian:</span>\n                <span th:text="${eventStartTime}">Thời gian</span>\n            </div>\n        </div>\n\n        <div class="custom-body" th:utext="${customBody}">\n            Nội dung nhắc nhở từ ban tổ chức.\n        </div>\n\n        <div class="footer">\n            <p>&copy; 2026 Alumniverse - Hệ Thống Alumni HCMUS. Tất cả quyền được bảo lưu.</p>\n            <p>Email này được gửi tự động. Vui lòng không trả lời trực tiếp.</p>\n        </div>\n    </div>\n</body>\n</html>\n	Email nhắc sự kiện. Subject và phần thân (customBody) được truyền động khi gửi.	[{"key":"eventTitle","label":"Tên sự kiện","sample":"Ngày hội việc làm 2026"},{"key":"eventLocation","label":"Địa điểm","sample":"Cơ sở Nguyễn Văn Cừ"},{"key":"eventStartTime","label":"Thời gian bắt đầu","sample":"08:00 15/08/2026"},{"key":"customBody","label":"Nội dung tuỳ chỉnh (HTML)","sample":"<p>Hẹn gặp bạn tại sự kiện!</p>"}]	\N	2026-07-11 16:36:54.660027+00
5	mentorApplicationReview	\N	<!DOCTYPE html>\n<html lang="vi" xmlns:th="http://www.thymeleaf.org">\n<head>\n    <meta charset="UTF-8">\n    <title>Cập nhật hồ sơ Mentor - AlumVerse</title>\n    <style>\n        body {\n            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n            background-color: #f5f5f5;\n            margin: 0;\n            padding: 0;\n        }\n        .container {\n            background-color: #ffffff;\n            max-width: 600px;\n            margin: 20px auto;\n            padding: 30px;\n            border-radius: 8px;\n            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);\n        }\n        .header {\n            border-bottom: 2px solid #1976d2;\n            padding-bottom: 16px;\n            margin-bottom: 24px;\n        }\n        .header h1 {\n            color: #1976d2;\n            margin: 0;\n            font-size: 22px;\n        }\n        .status-badge {\n            display: inline-block;\n            padding: 6px 14px;\n            border-radius: 999px;\n            color: #fff;\n            font-weight: 600;\n            font-size: 14px;\n            margin: 8px 0;\n        }\n        .status-APPROVED { background-color: #2e7d32; }\n        .status-REJECTED { background-color: #c62828; }\n        .status-NEED_UPDATE { background-color: #ef6c00; }\n        .reason-box {\n            background-color: #fafafa;\n            border-left: 4px solid #1976d2;\n            padding: 14px 18px;\n            margin: 18px 0;\n            color: #333;\n            white-space: pre-line;\n        }\n        .footer {\n            color: #888;\n            font-size: 13px;\n            margin-top: 28px;\n            border-top: 1px solid #eee;\n            padding-top: 16px;\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="header">\n            <h1>AlumVerse Mentorship</h1>\n        </div>\n\n        <p>Xin chào <strong th:text="${recipientName}">bạn</strong>,</p>\n\n        <p>Quản trị viên vừa cập nhật trạng thái hồ sơ Mentor của bạn:</p>\n\n        <p>\n            <span th:class="'status-badge status-' + ${status}" th:text="${statusLabel}">Status</span>\n        </p>\n\n        <div th:if="${reason != null and !reason.isEmpty()}" class="reason-box">\n            <strong>Lý do / Yêu cầu từ quản trị viên:</strong><br>\n            <span th:text="${reason}">reason</span>\n        </div>\n\n        <p th:if="${status == 'APPROVED'}">\n            Chúc mừng bạn! Hồ sơ Mentor đã được duyệt. Bạn có thể bắt đầu thiết lập lịch rảnh và\n            nhận yêu cầu mentoring từ mentee.\n        </p>\n\n        <p th:if="${status == 'NEED_UPDATE'}">\n            Vui lòng đăng nhập vào AlumVerse, chỉnh sửa hồ sơ theo yêu cầu ở trên và gửi lại để\n            được xét duyệt.\n        </p>\n\n        <p th:if="${status == 'REJECTED'}">\n            Bạn vẫn có thể chỉnh sửa hồ sơ và đăng ký lại sau khi đáp ứng các yêu cầu cộng đồng.\n        </p>\n\n        <div class="footer">\n            Email được gửi tự động từ hệ thống AlumVerse. Vui lòng không trả lời email này.\n        </div>\n    </div>\n</body>\n</html>\n	Email thông báo kết quả duyệt hồ sơ Mentor. Có nhánh điều kiện theo status (dùng chế độ HTML).	[{"key":"recipientName","label":"Tên người nhận","sample":"Nguyễn Văn A"},{"key":"status","label":"Trạng thái (APPROVED/REJECTED/NEED_UPDATE)","sample":"APPROVED"},{"key":"statusLabel","label":"Nhãn trạng thái","sample":"Đã duyệt"},{"key":"reason","label":"Lý do / yêu cầu","sample":"Hồ sơ đầy đủ."}]	\N	2026-07-11 16:36:54.659908+00
2	eventInvitation	\N	<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <title>Lời Mời Tham Gia Sự Kiện - Alumniverse</title>\n    <style>\n        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f5f5f5; margin: 0; padding: 0; }\n        .container { background-color: white; max-width: 600px; margin: 20px auto; padding: 30px; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }\n        .header { text-align: center; margin-bottom: 30px; border-bottom: 2px solid #667eea; padding-bottom: 20px; }\n        .header h1 { color: #333; margin: 0; font-size: 24px; }\n        .header p { color: #666; font-size: 14px; margin: 5px 0 0 0; }\n        .event-box { background-color: #f0f7ff; border-left: 4px solid #667eea; padding: 20px; margin: 20px 0; border-radius: 4px; }\n        .event-box .event-title { font-size: 18px; font-weight: bold; color: #333; margin-bottom: 12px; }\n        .event-detail { display: flex; margin: 8px 0; font-size: 14px; color: #555; }\n        .event-detail .label { color: #888; min-width: 100px; }\n        .action-button { text-align: center; margin: 30px 0; }\n        .action-button a { background-color: #667eea; color: white; padding: 14px 36px; text-decoration: none; border-radius: 6px; display: inline-block; font-weight: bold; font-size: 16px; }\n        .note { background-color: #fff3e0; border-left: 4px solid #ff9800; padding: 12px; margin: 15px 0; border-radius: 4px; font-size: 13px; color: #e65100; }\n        .footer { text-align: center; margin-top: 30px; padding-top: 20px; border-top: 1px solid #eee; font-size: 12px; color: #999; }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="header">\n            <h1><!--#region key="headerTitle" label="Tiêu đề chính" type="text"-->Bạn được mời tham gia sự kiện!<!--#endregion--></h1>\n            <p>Hệ Thống Quản Lý Sinh Viên - Cựu Sinh Viên HCMUS</p>\n        </div>\n\n        <p style="color: #333; font-size: 14px; line-height: 1.6;"><!--#region key="intro" label="Lời mời mở đầu" type="html"-->\n            Chúng tôi trân trọng kính mời bạn tham gia sự kiện sau:\n        <!--#endregion--></p>\n\n        <div class="event-box">\n            <div class="event-title" th:text="${eventTitle}">Tên sự kiện</div>\n            <div class="event-detail">\n                <span class="label">Địa điểm:</span>\n                <span th:text="${eventLocation}">Địa điểm</span>\n            </div>\n            <div class="event-detail">\n                <span class="label">Thời gian:</span>\n                <span th:text="${eventStartTime}">Thời gian</span>\n            </div>\n        </div>\n\n        <div class="action-button">\n            <a th:href="@{'/events/confirm?token=' + ${confirmToken}}"><!--#region key="buttonLabel" label="Nhãn nút xác nhận" type="text"-->Xác nhận tham gia<!--#endregion--></a>\n        </div>\n\n        <div class="note"><!--#region key="note" label="Ghi chú hiệu lực" type="html"-->\n            Lời mời này có hiệu lực trong <strong>7 ngày</strong>. Sau thời hạn, link xác nhận sẽ không còn hợp lệ.\n        <!--#endregion--></div>\n\n        <div class="footer"><!--#region key="footer" label="Chân trang" type="html"-->\n            <p>&copy; 2026 Alumniverse - Hệ Thống Alumni HCMUS. Tất cả quyền được bảo lưu.</p>\n            <p>Email này được gửi tự động. Vui lòng không trả lời trực tiếp.</p>\n        <!--#endregion--></div>\n    </div>\n</body>\n</html>\n	Thư mời tham gia sự kiện. Subject được tạo động từ tên sự kiện.	[{"key":"eventTitle","label":"Tên sự kiện","sample":"Ngày hội việc làm 2026"},{"key":"eventLocation","label":"Địa điểm","sample":"Cơ sở Nguyễn Văn Cừ"},{"key":"eventStartTime","label":"Thời gian bắt đầu","sample":"08:00 15/08/2026"},{"key":"confirmToken","label":"Token xác nhận","sample":"abc123token"}]	218	2026-07-19 14:26:11.870335+00
1	otpVerification	Xác minh OTP - Hệ Thống Alumni HCMUS	<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <title>Xác Minh OTP - Hệ Thống Alumni HCMUS</title>\n    <style>\n        body {\n            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n            background-color: #f5f5f5;\n            margin: 0;\n            padding: 0;\n        }\n\n        .container {\n            background-color: white;\n            max-width: 600px;\n            margin: 20px auto;\n            padding: 30px;\n            border-radius: 8px;\n            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);\n        }\n\n        .header {\n            text-align: center;\n            margin-bottom: 30px;\n            border-bottom: 2px solid #667eea;\n            padding-bottom: 20px;\n        }\n\n        .header h1 {\n            color: #333;\n            margin: 0;\n            font-size: 24px;\n        }\n\n        .header p {\n            color: #666;\n            font-size: 14px;\n            margin: 5px 0 0 0;\n        }\n\n        .content {\n            margin: 20px 0;\n            line-height: 1.6;\n        }\n\n        .alumni-info {\n            background-color: #f0f7ff;\n            border-left: 4px solid #667eea;\n            padding: 15px;\n            margin: 20px 0;\n            border-radius: 4px;\n        }\n\n        .alumni-info p {\n            margin: 0;\n            color: #333;\n            font-size: 14px;\n        }\n\n        .otp-box {\n            background-color: #f9f9f9;\n            border: 2px dashed #667eea;\n            padding: 20px;\n            margin: 20px 0;\n            text-align: center;\n            border-radius: 6px;\n        }\n\n        .otp-label {\n            color: #666;\n            font-size: 13px;\n            margin-bottom: 8px;\n            display: block;\n        }\n\n        .otp-code {\n            font-size: 32px;\n            font-weight: bold;\n            color: #667eea;\n            letter-spacing: 8px;\n            font-family: 'Courier New', monospace;\n        }\n\n        .info-text {\n            background-color: #e8f4f8;\n            border-left: 4px solid #3498db;\n            padding: 12px;\n            margin: 15px 0;\n            border-radius: 4px;\n            font-size: 13px;\n            color: #2c3e50;\n        }\n\n        .footer {\n            text-align: center;\n            margin-top: 30px;\n            padding-top: 20px;\n            border-top: 1px solid #eee;\n            font-size: 12px;\n            color: #999;\n        }\n\n        .footer p {\n            margin: 5px 0;\n        }\n\n        .contact {\n            background-color: #fff3cd;\n            border-left: 4px solid #ffc107;\n            padding: 12px;\n            margin: 15px 0;\n            border-radius: 4px;\n            font-size: 13px;\n            color: #856404;\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="header">\n            <h1>Xác Minh OTP</h1>\n            <p>Hệ Thống Quản Lý Sinh Viên - Cựu Sinh Viên HCMUS</p>\n        </div>\n\n        <div class="content">\n            <div class="alumni-info">\n                <p><strong>Chào mừng bạn!</strong></p>\n                <p>Để bảo vệ tài khoản Alumni của bạn, vui lòng sử dụng mã OTP dưới đây để xác minh địa chỉ email.</p>\n            </div>\n\n            <div class="otp-box">\n                <span class="otp-label">Mã xác minh OTP của bạn:</span>\n                <div class="otp-code" th:text="${otp}">123456</div>\n            </div>\n\n            <p style="color: #333; font-size: 14px;">\n                Mã OTP này sẽ hết hạn trong vòng <strong>5 phút</strong>. Vui lòng không chia sẻ mã này với bất kỳ ai.\n            </p>\n\n            <div class="info-text">\n                <strong>Lưu ý:</strong> Mã OTP này sẽ được ghi lại trong lịch sử xác minh tài khoản của bạn.\n            </div>\n\n            <div class="contact">\n                <strong>Cần hỗ trợ?</strong> Vui lòng liên hệ: support@alumni.hcmus.edu.vn hoặc gọi 1900-123-456\n            </div>\n        </div>\n\n        <div class="footer">\n            <p>&copy; 2026 Hệ Thống Alumni HCMUS. Tất cả quyền được bảo lưu.</p>\n        </div>\n    </div>\n</body>\n</html>\n	Email chứa mã OTP xác minh tài khoản/đổi email.	[{"key":"otp","label":"Mã OTP","sample":"123456"},{"key":"email","label":"Email người nhận","sample":"alumni@example.com"}]	\N	2026-07-11 16:36:54.659928+00
4	eventTicket	\N	<!DOCTYPE html>\r\n<html lang="vi">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <title>Vé Tham Dự Sự Kiện - Alumniverse</title>\r\n    <style>\r\n        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f5f5f5; margin: 0; padding: 0; }\r\n        .container { background-color: white; max-width: 600px; margin: 20px auto; padding: 30px; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }\r\n        .header { text-align: center; margin-bottom: 30px; border-bottom: 2px solid #667eea; padding-bottom: 20px; }\r\n        .header h1 { color: #333; margin: 0; font-size: 24px; }\r\n        .header p { color: #666; font-size: 14px; margin: 5px 0 0 0; }\r\n        .ticket { border: 2px dashed #667eea; border-radius: 8px; padding: 24px; margin: 20px 0; background-color: #fafbff; }\r\n        .ticket-title { font-size: 20px; font-weight: bold; color: #333; text-align: center; margin-bottom: 16px; }\r\n        .ticket-row { display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #eee; font-size: 14px; }\r\n        .ticket-row:last-child { border-bottom: none; }\r\n        .ticket-label { color: #888; }\r\n        .ticket-value { color: #333; font-weight: 500; }\r\n        .qr-section { text-align: center; margin: 24px 0; padding: 20px; background-color: #f0f7ff; border-radius: 6px; }\r\n        .qr-image { display: inline-block; margin-bottom: 12px; padding: 12px; background: #fff; border-radius: 10px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); }\r\n        .qr-image img { width: 220px; height: 220px; display: block; }\r\n        .qr-section .ticket-code { font-size: 28px; font-weight: bold; color: #667eea; letter-spacing: 4px; font-family: monospace; }\r\n        .qr-section p { color: #666; font-size: 13px; margin: 8px 0 0 0; }\r\n        .ticket-button { display: inline-block; margin-top: 16px; padding: 12px 18px; background: #667eea; color: #fff !important; text-decoration: none; border-radius: 999px; font-weight: 600; }\r\n        .success-badge { background-color: #e8f5e9; border-left: 4px solid #4caf50; padding: 12px; border-radius: 4px; font-size: 14px; color: #2e7d32; margin: 15px 0; }\r\n        .footer { text-align: center; margin-top: 30px; padding-top: 20px; border-top: 1px solid #eee; font-size: 12px; color: #999; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class="container">\r\n        <div class="header">\r\n            <h1><!--#region key="headerTitle" label="Tiêu đề chính" type="text"-->Vé tham dự sự kiện của bạn<!--#endregion--></h1>\r\n            <p>Hệ Thống Quản Lý Sinh Viên - Cựu Sinh Viên HCMUS</p>\r\n        </div>\r\n\r\n        <div class="success-badge"><!--#region key="badge" label="Thông báo xác nhận" type="html"-->\r\n                Đăng ký của bạn đã được xác nhận. Vui lòng mang theo mã vé này khi đến tham dự.\r\n        <!--#endregion--></div>\r\n\r\n        <div class="ticket">\r\n            <div class="ticket-title" th:text="${eventTitle}">Tên sự kiện</div>\r\n            <div class="ticket-row">\r\n                <span class="ticket-label">Địa điểm: </span>\r\n                <span class="ticket-value" th:text="${eventLocation}">Địa điểm</span>\r\n            </div>\r\n            <div class="ticket-row">\r\n                <span class="ticket-label">Thời gian: </span>\r\n                <span class="ticket-value" th:text="${eventStartTime}">Thời gian</span>\r\n            </div>\r\n        </div>\r\n\r\n        <div class="qr-section">\r\n            <div class="qr-image" th:if="${ticketQrContentId != null}">\r\n                <img th:src="'cid:' + ${ticketQrContentId}" alt="Mã QR vé tham dự" />\r\n            </div>\r\n            <p style="color: #555; margin-bottom: 12px;"><!--#region key="checkinLabel" label="Nhãn mã check-in" type="text"-->Mã check-in của bạn:<!--#endregion--></p>\r\n            <div class="ticket-code" th:text="${ticketCode}">ABC12345</div>\r\n            <p><!--#region key="checkinHint" label="Hướng dẫn check-in" type="text"-->Xuất trình mã này tại cổng để check-in<!--#endregion--></p>\r\n        </div>\r\n\r\n        <div class="footer"><!--#region key="footer" label="Chân trang" type="html"-->\r\n            <p>&copy; 2026 Alumniverse - Hệ Thống Alumni HCMUS. Tất cả quyền được bảo lưu.</p>\r\n            <p>Email này được gửi tự động. Vui lòng không trả lời trực tiếp.</p>\r\n        <!--#endregion--></div>\r\n    </div>\r\n</body>\r\n</html>\r\n	Email gửi vé tham dự sự kiện kèm mã vé.	[{"key":"eventTitle","label":"Tên sự kiện","sample":"Ngày hội việc làm 2026"},{"key":"eventLocation","label":"Địa điểm","sample":"Cơ sở Nguyễn Văn Cừ"},{"key":"eventStartTime","label":"Thời gian bắt đầu","sample":"08:00 15/08/2026"},{"key":"guestName","label":"Tên khách","sample":"Nguyễn Văn A"},{"key":"ticketCode","label":"Mã vé","sample":"TICKET-0001"}]	\N	2026-07-19 17:01:40.702788+00
6	donationThankYou	\N	<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <title>Cảm Ơn Về Danh Nghĩa Quyên Góp - Hệ Thống Alumni HCMUS</title>\n    <style>\n        body {\n            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n            background-color: #f5f5f5;\n            margin: 0;\n            padding: 0;\n        }\n\n        .container {\n            background-color: white;\n            max-width: 600px;\n            margin: 20px auto;\n            padding: 30px;\n            border-radius: 8px;\n            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);\n        }\n\n        .header {\n            text-align: center;\n            margin-bottom: 30px;\n            border-bottom: 2px solid #667eea;\n            padding-bottom: 20px;\n        }\n\n        .header h1 {\n            color: #333;\n            margin: 0;\n            font-size: 24px;\n        }\n\n        .header p {\n            color: #666;\n            font-size: 14px;\n            margin: 5px 0 0 0;\n        }\n\n        .content {\n            margin: 20px 0;\n            line-height: 1.6;\n        }\n\n        .greeting {\n            background-color: #f0f7ff;\n            border-left: 4px solid #667eea;\n            padding: 15px;\n            margin: 20px 0;\n            border-radius: 4px;\n        }\n\n        .greeting p {\n            margin: 0;\n            color: #333;\n            font-size: 14px;\n        }\n\n        .donation-box {\n            background-color: #f9f9f9;\n            border: 2px solid #667eea;\n            padding: 20px;\n            margin: 20px 0;\n            border-radius: 6px;\n        }\n\n        .donation-item {\n            display: flex;\n            justify-content: space-between;\n            margin: 12px 0;\n            padding: 8px 0;\n            border-bottom: 1px solid #eee;\n            color: #333;\n            font-size: 14px;\n        }\n\n        .donation-item:last-child {\n            border-bottom: none;\n            font-weight: bold;\n            border-top: 2px solid #667eea;\n            padding-top: 12px;\n            color: #667eea;\n        }\n\n        .donation-label {\n            color: #666;\n        }\n\n        .donation-value {\n            color: #333;\n            font-weight: 500;\n        }\n\n        .impact-section {\n            background-color: #e8f5e9;\n            border-left: 4px solid #4caf50;\n            padding: 15px;\n            margin: 15px 0;\n            border-radius: 4px;\n            font-size: 14px;\n            color: #2e7d32;\n        }\n\n        .impact-section strong {\n            display: block;\n            margin-bottom: 8px;\n        }\n\n        .recognition {\n            background-color: #fff3e0;\n            border-left: 4px solid #ff9800;\n            padding: 12px;\n            margin: 15px 0;\n            border-radius: 4px;\n            font-size: 13px;\n            color: #e65100;\n        }\n\n        .action-button {\n            text-align: center;\n            margin: 20px 0;\n        }\n\n        .action-button a {\n            background-color: #667eea;\n            color: white;\n            padding: 12px 30px;\n            text-decoration: none;\n            border-radius: 4px;\n            display: inline-block;\n            font-weight: bold;\n            font-size: 14px;\n        }\n\n        .action-button a:hover {\n            background-color: #5568d3;\n        }\n\n        .footer {\n            text-align: center;\n            margin-top: 30px;\n            padding-top: 20px;\n            border-top: 1px solid #eee;\n            font-size: 12px;\n            color: #999;\n        }\n\n        .footer p {\n            margin: 5px 0;\n        }\n\n        .contact {\n            background-color: #e3f2fd;\n            border-left: 4px solid #2196f3;\n            padding: 12px;\n            margin: 15px 0;\n            border-radius: 4px;\n            font-size: 13px;\n            color: #1565c0;\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="header">\n            <h1><!--#region key="headerTitle" label="Tiêu đề chính" type="text"-->Cảm Ơn Về Danh Nghĩa Quyên Góp<!--#endregion--></h1>\n            <p>Hệ Thống Quản Lý Sinh Viên - Cựu Sinh Viên HCMUS</p>\n        </div>\n\n        <div class="content">\n            <div class="greeting">\n                <p><strong>Kính chào <span th:text="${donorName}">Quý Khách</span>!</strong></p>\n                <p><!--#region key="thankYouMessage" label="Lời cảm ơn" type="html"-->Chúng tôi xin gửi lời cảm ơn chân thành nhất vì sự ủng hộ và đóng góp chung tay của bạn cho sự phát triển của Trường Đại học Khoa học Tự nhiên - HCMUS.<!--#endregion--></p>\n            </div>\n\n            <div class="donation-box">\n                <div class="donation-item">\n                    <span class="donation-label">Ngày quyên góp:</span>\n                    <span class="donation-value" th:text="${donationDate}">20/03/2026</span>\n                </div>\n                <div class="donation-item">\n                    <span class="donation-label">Số tiền quyên góp:</span>\n                    <span class="donation-value" th:text="${donationAmount}">1,000,000 VND</span>\n                </div>\n                <div class="donation-item">\n                    <span class="donation-label">Mục đích quyên góp:</span>\n                    <span class="donation-value" th:text="${donationPurpose}">Hỗ trợ sinh viên có hoàn cảnh khó khăn</span>\n                </div>\n                <div class="donation-item">\n                    <span class="donation-label">Mã tham chiếu:</span>\n                    <span class="donation-value" th:text="${referenceNumber}">SKS-2026-001234</span>\n                </div>\n            </div>\n\n            <div class="impact-section"><!--#region key="impact" label="Tác động quyên góp" type="html"-->\n                <strong>💡 Những tác động của sự quyên góp của bạn:</strong>\n                Đóng góp của bạn sẽ giúp chúng tôi:\n                <ul style="margin: 8px 0; padding-left: 20px;">\n                    <li>Hỗ trợ sinh viên xuất sắc nhưng có hoàn cảnh khó khăn</li>\n                    <li>Phát triển cơ sở vật chất và thiết bị giáo dục</li>\n                    <li>Tố chức các chương trình giao lưu, hội thảo</li>\n                    <li>Nâng cao chất lượng giáo dục và đào tạo</li>\n                </ul>\n            <!--#endregion--></div>\n\n            <div class="recognition"><!--#region key="recognition" label="Sự công nhận" type="html"-->\n                <strong>🌟 Sự công nhận:</strong> Tên quý khách sẽ được ghi danh trong sổ nhân sĩ ủng hộ giáo dục và có cơ hội xác nhận công khai nếu muốn.\n            <!--#endregion--></div>\n\n            <div class="action-button">\n                <a href="javascript:void(0);" th:href="@{/alumni/donation-history}"><!--#region key="buttonLabel" label="Nhãn nút" type="text"-->Xem Lịch Sử Quyên Góp<!--#endregion--></a>\n            </div>\n\n            <div class="contact"><!--#region key="contact" label="Thông tin hỗ trợ" type="html"-->\n                <strong>Cần hỗ trợ?</strong> Vui lòng liên hệ: support@alumni.hcmus.edu.vn hoặc gọi 1900-123-456\n            <!--#endregion--></div>\n        </div>\n\n        <div class="footer"><!--#region key="footer" label="Chân trang" type="html"-->\n            <p>&copy; 2026 Hệ Thống Alumni HCMUS. Tất cả quyền được bảo lưu.</p>\n            <p>Email này được gửi tự động. Vui lòng không trả lời trực tiếp.</p>\n        <!--#endregion--></div>\n    </div>\n</body>\n</html>	Email cảm ơn quyên góp.	[{"key":"donorName","label":"Tên nhà hảo tâm","sample":"Nguyễn Văn A"},{"key":"donationAmount","label":"Số tiền","sample":"1.000.000đ"},{"key":"donationDate","label":"Ngày quyên góp","sample":"15/08/2026"},{"key":"donationPurpose","label":"Mục đích","sample":"Quỹ học bổng"},{"key":"referenceNumber","label":"Mã tham chiếu","sample":"REF-0001"}]	14	2026-07-12 15:44:17.548448+00
